    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Independent web developer creating clean, thoughtful digital experiences.">
    <title>Portfolio — Web Developer</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <a class="skip-link" href="#main-content">Skip to content</a>

    <header class="site-header">
        <a class="logo" href="#" aria-label="Portfolio home">
            <span class="logo-mark">P</span>
            <span>Portfolio</span>
        </a>

        <a class="header-link" href="#contact">Let's talk</a>
    </header>

    <main id="main-content">
        <section class="hero" aria-labelledby="hero-title">
            <div class="hero-glow hero-glow-one" aria-hidden="true"></div>
            <div class="hero-glow hero-glow-two" aria-hidden="true"></div>

            <div class="hero-content">
                <p class="eyebrow">
                    <span class="status-dot" aria-hidden="true"></span>
                    Available for new projects
                </p>

                <h1 id="hero-title">
                    I build thoughtful
                    <span>digital experiences.</span>
                </h1>

                <p class="hero-copy">
                    I combine thoughtful design with clean, reliable code to create
                    websites that feel simple, work beautifully, and leave a lasting impression.
                </p>

                <div class="hero-actions">
                    <a class="button button-primary" href="#contact">
                        Start a project
                        <span aria-hidden="true">↗</span>
                    </a>
                    <a class="button button-secondary" href="#work">
                        View my work
                    </a>
                </div>
            </div>

            <div class="hero-note" aria-label="Specialties">
                <span>Design</span>
                <span>Development</span>
                <span>Strategy</span>
            </div>
        </section>
    </main>
</body>
