```css:style.css
:root {
    color-scheme: dark;
    --background: #09090b;
    --surface: rgba(255, 255, 255, 0.04);
    --text: #f4f4f5;
    --muted: #a1a1aa;
    --border: rgba(255, 255, 255, 0.1);
    --accent: #a3e635;
    --accent-dark: #1a2e05;
}

*,
*::before,
*::after {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    min-height: 100vh;
    margin: 0;
    overflow-x: hidden;
    background: var(--background);
    color: var(--text);
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    -webkit-font-smoothing: antialiased;
}

a {
    color: inherit;
    text-decoration: none;
}

.skip-link {
    position: fixed;
    top: 1rem;
    left: 1rem;
    z-index: 100;
    padding: 0.75rem 1rem;
    border-radius: 0.5rem;
    background: var(--accent);
    color: var(--accent-dark);
    font-weight: 700;
    transform: translateY(-200%);
    transition: transform 180ms ease;
}

.skip-link:focus {
    transform: translateY(0);
}

.site-header {
    position: relative;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: min(1180px, calc(100% - 3rem));
    margin: 0 auto;
    padding: 1.5rem 0;
}

.logo {
    display: inline-flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: -0.01em;
}

.logo-mark {
    display: grid;
    width: 2rem;
    height: 2rem;
    place-items: center;
    border: 1px solid var(--border);
    border-radius: 0.6rem;
    background: var(--surface);
    color: var(--accent);
    font-size: 0.85rem;
}

.header-link {
    color: var(--muted);
    font-size: 0.9rem;
    font-weight: 600;
    transition: color 180ms ease;
}

.header-link:hover,
.header-link:focus-visible {
    color: var(--text);
}

.hero {
    position: relative;
    display: flex;
    min-height: calc(100vh - 5rem);
    width: min(1180px, calc(100% - 3rem));
    margin: 0 auto;
    padding: clamp(5rem, 14vh, 9rem) 0 4rem;
    align-items: center;
    isolation: isolate;
}

.hero::before {
    position: absolute;
    z-index: -2;
    inset: 0;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px);
    background-size: 64px 64px;
    mask-image: linear-gradient(to bottom, black, transparent 78%);
    content: "";
}

.hero-glow {
    position: absolute;
    z-index: -1;
    width: 28rem;
    height: 28rem;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.11;
    pointer-events: none;
}

.hero-glow-one {
    top: 5%;
    right: -10rem;
    background: var(--accent);
}

.hero-glow-two {
    bottom: -12rem;
    left: -10rem;
    background: #38bdf8;
}

.hero-content {
    max-width: 880px;
}

.eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.65rem;
    margin: 0 0 1.75rem;
    padding: 0.55rem 0.8rem;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.035);
    color: #d4d4d8;
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0.01em;
    backdrop-filter: blur(12px);
}

.status-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 0 5px rgba(163, 230, 53, 0.1);
}

h1 {
    max-width: 850px;
    margin: 0;
    font-size: clamp(3.3rem, 8vw, 6.8rem);
    font-weight: 650;
    line-height: 0.98;
    letter-spacing: -0.065em;
}

h1 span {
    display: block;
    background: linear-gradient(110deg, var(--text) 10%, #71717a 85%);
    background-clip: text;
    color: transparent;
    -webkit-background-clip: text;
}

.hero-copy {
    max-width: 650px;
    margin: 2rem 0 0;
    color: var(--muted);
    font-size: clamp(1rem, 2vw, 1.2rem);
    line-height: 1.75;
}

.hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.8rem;
    margin-top: 2.25rem;
}

.button {
    display: inline-flex;
    min-height: 3.2rem;
    padding: 0.8rem 1.2rem;
    align-items: center;
    justify-content: center;
    gap: 0.65rem;
    border: 1px solid transparent;
    border-radius: 0.75rem;
    font-size: 0.9rem;
    font-weight: 700;
    transition: transform 180ms ease, background-color 180ms ease, border-color 180ms ease;
}

.button:hover {
    transform: translateY(-2px);
}

.button:focus-visible,
.header-link:focus-visible,
.logo:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 4px;
}

.button-primary {
    background: var(--accent);
    color: var(--accent-dark);
    box-shadow: 0 12px 35px rgba(163, 230, 53, 0.12);
}

.button-primary:hover {
    background: #b4f052;
}

.button-secondary {
    border-color: var(--border);
    background: var(--surface);
    color: var(--text);
}

.button-secondary:hover {
    border-color: rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.07);
}

.hero-note {
    position: absolute;
    right: 0;
    bottom: 2rem;
    display: flex;
    gap: 1.5rem;
    color: #52525b;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

.hero-note span {
    position: relative;
}

.hero-note span:not(:last-child)::after {
    position: absolute;
    top: 50%;
    right: -0.85rem;
    width: 0.25rem;
    height: 0.25rem;
    border-radius: 50%;
    background: #3f3f46;
    content: "";
}

@media (max-width: 700px) {
    .site-header,
    .hero {
        width: min(100% - 2rem, 1180px);
    }

    .site-header {
        padding: 1.1rem 0;
    }

    .hero {
        min-height: calc(100vh - 4.2rem);
        padding: 4rem 0 7rem;
        align-items: flex-start;
    }

    h1 {
        font-size: clamp(3rem, 15vw, 4.8rem);
    }

    .hero-copy {
        line-height: 1.65;
    }

    .hero-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .button {
        width: 100%;
    }

    .hero-note {
        right: auto;
        bottom: 2rem;
        left: 0;
        gap: 1rem;
        font-size: 0.62rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    .button,
    .header-link,
    .skip-link {
        transition: none;
    }
}
```

