        transparent 0,
        transparent 42px,
        rgba(255, 255, 255, 0.13) 42px,
        rgba(255, 255, 255, 0.13) 44px,
        transparent 44px,
        transparent 92px
    );
    background-size: 180px 100%;
    mask-image: linear-gradient(90deg, transparent, #000 25%, #000 75%, transparent);
    opacity: 0.65;
    animation: road-speed 750ms linear infinite;
